// AscendC MultiMaskAttentionAggregation kernel
// Strategies: whole_r (ref_seq_len <= 1024), split_r (ref_seq_len > 1024)
// Supports float32, float16, bfloat16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t DEFAULT_BLOCK_X = 4;
constexpr int32_t DEFAULT_BLOCK_R = 512;
constexpr float EPS = 1e-10f;
constexpr float NEG_INF = -3.402823e+38f;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareFloatTensor(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Strategy 1: whole_r — preferred when ref_seq_len <= 1024
// =========================================================================

template <typename dataType>
class WholeRKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR attn, GM_ADDR masks, GM_ADDR output,
        int32_t B, int32_t H, int32_t xSeqLen, int32_t refSeqLen, int32_t numClasses,
        int32_t usedCoreNum, int32_t tasksPerCore, int64_t modeFlag)
    {
        this->B = B;
        this->H = H;
        this->xSeqLen = xSeqLen;
        this->refSeqLen = refSeqLen;
        this->numClasses = numClasses;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->modeFlag = modeFlag;

        uint64_t attnSize = static_cast<uint64_t>(B) * H * xSeqLen * refSeqLen;
        uint64_t maskSize = static_cast<uint64_t>(numClasses) * refSeqLen;
        uint64_t outSize = static_cast<uint64_t>(numClasses) * B * xSeqLen;

        attnGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(attn), attnSize);
        masksGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(masks), maskSize);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), outSize);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int xNumTiles = CeilDivI32(xSeqLen, DEFAULT_BLOCK_X);
            const int totalTasks = numClasses * B * xNumTiles;

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int taskId = coreIdx * tasksPerCore + localIdx;
                if (taskId >= totalTasks) { continue; }

                const int classIdx = taskId / (B * xNumTiles);
                const int rem = taskId % (B * xNumTiles);
                const int batchIdx = rem / xNumTiles;
                const int xTileIdx = rem % xNumTiles;
                const int xStart = xTileIdx * DEFAULT_BLOCK_X;
                const int curBlockX = (xStart + DEFAULT_BLOCK_X <= xSeqLen) ? DEFAULT_BLOCK_X : (xSeqLen - xStart);

                ProcessBlock(classIdx, batchIdx, xStart, curBlockX);
            }
        }
    }

private:
    __aicore__ inline void InitAivBuffers()
    {
        pipe.InitBuffer(aInQueue_, BUFFER_NUM, refSeqLen * sizeof(dataType));
        pipe.InitBuffer(mInQueue_, BUFFER_NUM, refSeqLen * sizeof(dataType));
        pipe.InitBuffer(outQueue_, BUFFER_NUM, DEFAULT_BLOCK_X * sizeof(dataType));
        pipe.InitBuffer(tmpBuf_, refSeqLen * sizeof(float));
        pipe.InitBuffer(softBuf_, refSeqLen * sizeof(float));
        pipe.InitBuffer(maskFpBuf_, refSeqLen * sizeof(float));
        pipe.InitBuffer(reduceBuf_, 2 * refSeqLen * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe.InitBuffer(accBuf_, DEFAULT_BLOCK_X * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(aCastBuf_, refSeqLen * sizeof(float));
            pipe.InitBuffer(mCastBuf_, refSeqLen * sizeof(float));
            pipe.InitBuffer(outCastBuf_, DEFAULT_BLOCK_X * sizeof(float));
        }
    }

    __aicore__ inline float ComputeMaskSum(int32_t classIdx)
    {
        // Load mask row and reduce sum
        mInLocal_ = mInQueue_.AllocTensor<dataType>();
        LoadGmToUb(mInLocal_, masksGM_[static_cast<uint64_t>(classIdx) * refSeqLen], refSeqLen);
        mInQueue_.EnQue(mInLocal_);

        mInLocal_ = mInQueue_.DeQue<dataType>();
        PrepareFloatTensor<dataType>(maskFpLocal_, mInLocal_, mCastBuf_, refSeqLen);
        mInQueue_.FreeTensor(mInLocal_);

        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        AscendC::ReduceSum<float>(sumLocal_, maskFpLocal_, reduceTmpLocal_, refSeqLen);

        float maskSum = sumLocal_.GetValue(0);
        PipeBarrier<PIPE_ALL>();
        return (maskSum < EPS) ? 1.0f : maskSum;
    }

    __aicore__ inline void CopyInAttn(int32_t batchIdx, int32_t headIdx, int32_t xPos)
    {
        aInLocal_ = aInQueue_.AllocTensor<dataType>();
        uint64_t offset = (static_cast<uint64_t>(batchIdx) * H * xSeqLen +
                          static_cast<uint64_t>(headIdx) * xSeqLen + xPos) * refSeqLen;
        LoadGmToUb(aInLocal_, attnGM_[offset], refSeqLen);
        aInQueue_.EnQue(aInLocal_);
    }

    __aicore__ inline void CopyInMask(int32_t classIdx)
    {
        mInLocal_ = mInQueue_.AllocTensor<dataType>();
        LoadGmToUb(mInLocal_, masksGM_[static_cast<uint64_t>(classIdx) * refSeqLen], refSeqLen);
        mInQueue_.EnQue(mInLocal_);
    }

    __aicore__ inline void CopyOutResult(int32_t classIdx, int32_t batchIdx, int32_t xStart, int32_t count)
    {
        outLocal_ = outQueue_.DeQue<dataType>();
        uint64_t outOffset = static_cast<uint64_t>(classIdx) * B * xSeqLen +
                             static_cast<uint64_t>(batchIdx) * xSeqLen + xStart;
        StoreUbToGm(outGM_[outOffset], outLocal_, count);
        outQueue_.FreeTensor(outLocal_);
    }

    __aicore__ inline void ComputeSoftmaxAndMaskedSum(int32_t batchIdx, int32_t headIdx, int32_t xPos,
                                                       float maskSum, float &normResult)
    {
        // Dequeue attn row
        aInLocal_ = aInQueue_.DeQue<dataType>();
        PrepareFloatTensor<dataType>(aFpLocal_, aInLocal_, aCastBuf_, refSeqLen);

        // Load mask row
        CopyInMask(classStored_);
        mInLocal_ = mInQueue_.DeQue<dataType>();
        PrepareFloatTensor<dataType>(maskFpLocal_, mInLocal_, mCastBuf_, refSeqLen);

        tmpFpLocal_ = tmpBuf_.Get<float>();
        softFpLocal_ = softBuf_.Get<float>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();

        // Step 1: Softmax along refSeqLen
        // 1a: Find max
        AscendC::ReduceMax<float>(sumLocal_, aFpLocal_, reduceTmpLocal_, refSeqLen);
        PipeBarrier<PIPE_ALL>();
        float maxVal = sumLocal_.GetValue(0);

        // 1b: exp(x - max)
        AscendC::Subs(softFpLocal_, aFpLocal_, maxVal, refSeqLen);
        AscendC::Exp(softFpLocal_, softFpLocal_, refSeqLen);

        // 1c: Sum of exp for denominator
        AscendC::ReduceSum<float>(sumLocal_, softFpLocal_, reduceTmpLocal_, refSeqLen);
        PipeBarrier<PIPE_ALL>();
        float expSum = sumLocal_.GetValue(0);
        if (expSum < EPS) { expSum = EPS; }
        float invExpSum = 1.0f / expSum;

        // 1d: Divide by sum (softmax result now in softFpLocal_)
        AscendC::Muls(softFpLocal_, softFpLocal_, invExpSum, refSeqLen);

        // Step 2-4: Mask multiply + sum + normalize
        AscendC::Mul(tmpFpLocal_, softFpLocal_, maskFpLocal_, refSeqLen);
        AscendC::ReduceSum<float>(sumLocal_, tmpFpLocal_, reduceTmpLocal_, refSeqLen);
        PipeBarrier<PIPE_ALL>();
        float maskedSum = sumLocal_.GetValue(0);

        normResult = maskedSum / maskSum;

        aInQueue_.FreeTensor(aInLocal_);
        mInQueue_.FreeTensor(mInLocal_);
    }

    __aicore__ inline void ProcessBlock(int32_t classIdx, int32_t batchIdx, int32_t xStart,
                                         int32_t curBlockX)
    {
        classStored_ = classIdx;

        // Precompute mask sum for this class
        float maskSum = ComputeMaskSum();

        // Initialize accumulator
        accLocal_ = accBuf_.Get<float>();
        if (modeFlag == 1) { // max mode
            AscendC::Duplicate(accLocal_, NEG_INF, curBlockX);
        } else { // mean mode
            AscendC::Duplicate(accLocal_, 0.0f, curBlockX);
        }

        // Process each head
        for (int32_t h = 0; h < H; ++h) {
            for (int32_t rx = 0; rx < curBlockX; ++rx) {
                int32_t xPos = xStart + rx;

                CopyInAttn(batchIdx, h, xPos);

                float normResult;
                ComputeSoftmaxAndMaskedSum(batchIdx, h, xPos, maskSum, normResult);

                // Accumulate over H
                if (modeFlag == 1) { // max
                    float curAcc = accLocal_.GetValue(rx);
                    if (normResult > curAcc) {
                        AscendC::Duplicate(accLocal_, normResult, 1); // TODO: fix scalar element set
                        accLocal_.SetValue(rx, normResult);
                    }
                } else { // mean
                    float curAcc = accLocal_.GetValue(rx);
                    accLocal_.SetValue(rx, curAcc + normResult);
                }
            }
        }

        // Final scaling for mean mode
        if (modeFlag == 0) {
            float invH = 1.0f / static_cast<float>(H);
            AscendC::Muls(accLocal_, accLocal_, invH, curBlockX);
        }

        // Write output
        outLocal_ = outQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            outFpLocal_ = outLocal_.template ReinterpretCast<float>();
        } else {
            outFpLocal_ = outCastBuf_.Get<float>();
        }
        // Copy accumulator values to output buffer (element-by-element for now)
        for (int32_t rx = 0; rx < curBlockX; ++rx) {
            outFpLocal_.SetValue(rx, accLocal_.GetValue(rx));
        }
        FinalizeOutput<dataType>(outLocal_, outFpLocal_, curBlockX);
        outQueue_.EnQue(outLocal_);

        CopyOutResult(classIdx, batchIdx, xStart, curBlockX);
    }

private:
    int32_t B = 0;
    int32_t H = 0;
    int32_t xSeqLen = 0;
    int32_t refSeqLen = 0;
    int32_t numClasses = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int64_t modeFlag = 0;
    int32_t classStored_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> attnGM_;
    AscendC::GlobalTensor<dataType> masksGM_;
    AscendC::GlobalTensor<dataType> outGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> aInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> mInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> softBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskFpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> aCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outCastBuf_;

    AscendC::LocalTensor<dataType> aInLocal_;
    AscendC::LocalTensor<dataType> mInLocal_;
    AscendC::LocalTensor<dataType> outLocal_;
    AscendC::LocalTensor<float> aFpLocal_;
    AscendC::LocalTensor<float> maskFpLocal_;
    AscendC::LocalTensor<float> tmpFpLocal_;
    AscendC::LocalTensor<float> softFpLocal_;
    AscendC::LocalTensor<float> outFpLocal_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> accLocal_;
};

// =========================================================================
// Strategy 2: split_r — preferred when ref_seq_len > 1024
// =========================================================================

template <typename dataType>
class SplitRKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR attn, GM_ADDR masks, GM_ADDR output,
        int32_t B, int32_t H, int32_t xSeqLen, int32_t refSeqLen, int32_t numClasses,
        int32_t usedCoreNum, int32_t tasksPerCore, int64_t modeFlag)
    {
        this->B = B;
        this->H = H;
        this->xSeqLen = xSeqLen;
        this->refSeqLen = refSeqLen;
        this->numClasses = numClasses;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->modeFlag = modeFlag;

        uint64_t attnSize = static_cast<uint64_t>(B) * H * xSeqLen * refSeqLen;
        uint64_t maskSize = static_cast<uint64_t>(numClasses) * refSeqLen;
        uint64_t outSize = static_cast<uint64_t>(numClasses) * B * xSeqLen;

        attnGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(attn), attnSize);
        masksGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(masks), maskSize);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), outSize);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int xNumTiles = CeilDivI32(xSeqLen, DEFAULT_BLOCK_X);
            const int totalTasks = numClasses * B * xNumTiles;

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int taskId = coreIdx * tasksPerCore + localIdx;
                if (taskId >= totalTasks) { continue; }

                const int classIdx = taskId / (B * xNumTiles);
                const int rem = taskId % (B * xNumTiles);
                const int batchIdx = rem / xNumTiles;
                const int xTileIdx = rem % xNumTiles;
                const int xStart = xTileIdx * DEFAULT_BLOCK_X;
                const int curBlockX = (xStart + DEFAULT_BLOCK_X <= xSeqLen) ? DEFAULT_BLOCK_X : (xSeqLen - xStart);

                ProcessBlockSplit(classIdx, batchIdx, xStart, curBlockX);
            }
        }
    }

private:
    __aicore__ inline int32_t NumRTiles() const
    {
        return CeilDivI32(refSeqLen, DEFAULT_BLOCK_R);
    }

    __aicore__ inline int32_t GetValidR(int32_t rStart) const
    {
        return (rStart + DEFAULT_BLOCK_R <= refSeqLen) ? DEFAULT_BLOCK_R : (refSeqLen - rStart);
    }

    __aicore__ inline void InitAivBuffers()
    {
        pipe.InitBuffer(aInQueue_, BUFFER_NUM, DEFAULT_BLOCK_R * sizeof(dataType));
        pipe.InitBuffer(mInQueue_, BUFFER_NUM, DEFAULT_BLOCK_R * sizeof(dataType));
        pipe.InitBuffer(outQueue_, BUFFER_NUM, DEFAULT_BLOCK_X * sizeof(dataType));
        pipe.InitBuffer(tmpBuf_, DEFAULT_BLOCK_R * sizeof(float));
        pipe.InitBuffer(softBuf_, DEFAULT_BLOCK_R * sizeof(float));
        pipe.InitBuffer(maskFpBuf_, DEFAULT_BLOCK_R * sizeof(float));
        pipe.InitBuffer(reduceBuf_, 2 * DEFAULT_BLOCK_R * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe.InitBuffer(accBuf_, DEFAULT_BLOCK_X * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(aCastBuf_, DEFAULT_BLOCK_R * sizeof(float));
            pipe.InitBuffer(mCastBuf_, DEFAULT_BLOCK_R * sizeof(float));
            pipe.InitBuffer(outCastBuf_, DEFAULT_BLOCK_X * sizeof(float));
        }
    }

    __aicore__ inline void CopyInAttnTile(int32_t batchIdx, int32_t headIdx, int32_t xPos,
                                           int32_t rStart, int32_t validR)
    {
        aInLocal_ = aInQueue_.AllocTensor<dataType>();
        uint64_t offset = (static_cast<uint64_t>(batchIdx) * H * xSeqLen +
                          static_cast<uint64_t>(headIdx) * xSeqLen + xPos) * refSeqLen + rStart;
        LoadGmToUb(aInLocal_, attnGM_[offset], validR);
        aInQueue_.EnQue(aInLocal_);
    }

    __aicore__ inline void CopyInMaskTile(int32_t classIdx, int32_t rStart, int32_t validR)
    {
        mInLocal_ = mInQueue_.AllocTensor<dataType>();
        LoadGmToUb(mInLocal_, masksGM_[static_cast<uint64_t>(classIdx) * refSeqLen + rStart], validR);
        mInQueue_.EnQue(mInLocal_);
    }

    __aicore__ inline void CopyOutResultSplit(int32_t classIdx, int32_t batchIdx, int32_t xStart, int32_t count)
    {
        outLocal_ = outQueue_.DeQue<dataType>();
        uint64_t outOffset = static_cast<uint64_t>(classIdx) * B * xSeqLen +
                             static_cast<uint64_t>(batchIdx) * xSeqLen + xStart;
        StoreUbToGm(outGM_[outOffset], outLocal_, count);
        outQueue_.FreeTensor(outLocal_);
    }

    __aicore__ inline float FindGlobalMaxAndComputeMaskSum(int32_t classIdx, int32_t batchIdx,
                                                            int32_t headIdx, int32_t xPos,
                                                            float &maskSumOut)
    {
        // Two-pass: first find global max across all ref tiles, also accumulate mask sum
        float globalMax = NEG_INF;
        float maskSum = 0.0f;

        sumLocal_ = sumBuf_.Get<float>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();

        // First pass: find global max and preload mask once for per-tile computation
        for (int32_t br = 0; br < NumRTiles(); ++br) {
            int32_t rStart = br * DEFAULT_BLOCK_R;
            int32_t validR = GetValidR(rStart);

            CopyInAttnTile(batchIdx, headIdx, xPos, rStart, validR);
            aInLocal_ = aInQueue_.DeQue<dataType>();
            PrepareFloatTensor<dataType>(aFpLocal_, aInLocal_, aCastBuf_, validR);

            AscendC::ReduceMax<float>(sumLocal_, aFpLocal_, reduceTmpLocal_, validR);
            PipeBarrier<PIPE_ALL>();
            float tileMax = sumLocal_.GetValue(0);
            if (tileMax > globalMax) { globalMax = tileMax; }

            aInQueue_.FreeTensor(aInLocal_);
        }

        // Second pass: compute mask sum (only once per class)
        for (int32_t br = 0; br < NumRTiles(); ++br) {
            int32_t rStart = br * DEFAULT_BLOCK_R;
            int32_t validR = GetValidR(rStart);

            CopyInMaskTile(classIdx, rStart, validR);
            mInLocal_ = mInQueue_.DeQue<dataType>();
            PrepareFloatTensor<dataType>(maskFpLocal_, mInLocal_, mCastBuf_, validR);

            AscendC::ReduceSum<float>(sumLocal_, maskFpLocal_, reduceTmpLocal_, validR);
            PipeBarrier<PIPE_ALL>();
            maskSum += sumLocal_.GetValue(0);

            mInQueue_.FreeTensor(mInLocal_);
        }

        maskSumOut = (maskSum < EPS) ? 1.0f : maskSum;
        return globalMax;
    }

    __aicore__ inline float ComputeSoftmaxDenomAndMaskedSum(int32_t batchIdx, int32_t headIdx, int32_t xPos,
                                                             int32_t classIdx, float globalMax)
    {
        float expSum = 0.0f;
        float maskedSum = 0.0f;

        sumLocal_ = sumBuf_.Get<float>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();

        for (int32_t br = 0; br < NumRTiles(); ++br) {
            int32_t rStart = br * DEFAULT_BLOCK_R;
            int32_t validR = GetValidR(rStart);

            CopyInAttnTile(batchIdx, headIdx, xPos, rStart, validR);
            CopyInMaskTile(classIdx, rStart, validR);

            aInLocal_ = aInQueue_.DeQue<dataType>();
            mInLocal_ = mInQueue_.DeQue<dataType>();
            PrepareFloatTensor<dataType>(aFpLocal_, aInLocal_, aCastBuf_, validR);
            PrepareFloatTensor<dataType>(maskFpLocal_, mInLocal_, mCastBuf_, validR);

            tmpFpLocal_ = tmpBuf_.Get<float>();
            softFpLocal_ = softBuf_.Get<float>();

            // exp(attn - globalMax)
            AscendC::Subs(softFpLocal_, aFpLocal_, globalMax, validR);
            AscendC::Exp(softFpLocal_, softFpLocal_, validR);

            // Accumulate exp sum (softmax denominator)
            AscendC::ReduceSum<float>(sumLocal_, softFpLocal_, reduceTmpLocal_, validR);
            PipeBarrier<PIPE_ALL>();
            expSum += sumLocal_.GetValue(0);

            // Mask multiply and accumulate masked sum
            AscendC::Mul(tmpFpLocal_, softFpLocal_, maskFpLocal_, validR);
            AscendC::ReduceSum<float>(sumLocal_, tmpFpLocal_, reduceTmpLocal_, validR);
            PipeBarrier<PIPE_ALL>();
            maskedSum += sumLocal_.GetValue(0);

            aInQueue_.FreeTensor(aInLocal_);
            mInQueue_.FreeTensor(mInLocal_);
        }

        if (expSum < EPS) { expSum = EPS; }
        return maskedSum / expSum; // normalized masked sum
    }

    __aicore__ inline void ProcessBlockSplit(int32_t classIdx, int32_t batchIdx, int32_t xStart,
                                              int32_t curBlockX)
    {
        // Initialize accumulator
        accLocal_ = accBuf_.Get<float>();
        if (modeFlag == 1) {
            AscendC::Duplicate(accLocal_, NEG_INF, curBlockX);
        } else {
            AscendC::Duplicate(accLocal_, 0.0f, curBlockX);
        }

        // Process each head
        for (int32_t h = 0; h < H; ++h) {
            for (int32_t rx = 0; rx < curBlockX; ++rx) {
                int32_t xPos = xStart + rx;

                // Pass 1: find global max and mask sum
                float maskSumVal;
                float globalMax = FindGlobalMaxAndComputeMaskSum(classIdx, batchIdx, h, xPos, maskSumVal);

                // Pass 2: compute softmax + masked sum
                float normResult = ComputeSoftmaxDenomAndMaskedSum(batchIdx, h, xPos, classIdx, globalMax);
                normResult = normResult / maskSumVal;

                // Accumulate over H
                if (modeFlag == 1) {
                    float curAcc = accLocal_.GetValue(rx);
                    if (normResult > curAcc) {
                        accLocal_.SetValue(rx, normResult);
                    }
                } else {
                    float curAcc = accLocal_.GetValue(rx);
                    accLocal_.SetValue(rx, curAcc + normResult);
                }
            }
        }

        // Final scaling for mean mode
        if (modeFlag == 0) {
            float invH = 1.0f / static_cast<float>(H);
            AscendC::Muls(accLocal_, accLocal_, invH, curBlockX);
        }

        // Write output
        outLocal_ = outQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            outFpLocal_ = outLocal_.template ReinterpretCast<float>();
        } else {
            outFpLocal_ = outCastBuf_.Get<float>();
        }
        for (int32_t rx = 0; rx < curBlockX; ++rx) {
            outFpLocal_.SetValue(rx, accLocal_.GetValue(rx));
        }
        FinalizeOutput<dataType>(outLocal_, outFpLocal_, curBlockX);
        outQueue_.EnQue(outLocal_);

        CopyOutResultSplit(classIdx, batchIdx, xStart, curBlockX);
    }

private:
    int32_t B = 0;
    int32_t H = 0;
    int32_t xSeqLen = 0;
    int32_t refSeqLen = 0;
    int32_t numClasses = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int64_t modeFlag = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> attnGM_;
    AscendC::GlobalTensor<dataType> masksGM_;
    AscendC::GlobalTensor<dataType> outGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> aInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> mInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> softBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskFpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> aCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outCastBuf_;

    AscendC::LocalTensor<dataType> aInLocal_;
    AscendC::LocalTensor<dataType> mInLocal_;
    AscendC::LocalTensor<dataType> outLocal_;
    AscendC::LocalTensor<float> aFpLocal_;
    AscendC::LocalTensor<float> maskFpLocal_;
    AscendC::LocalTensor<float> tmpFpLocal_;
    AscendC::LocalTensor<float> softFpLocal_;
    AscendC::LocalTensor<float> outFpLocal_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> accLocal_;
};

// =========================================================================
// Dtype-dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchKernel(
    GM_ADDR attn, GM_ADDR masks, GM_ADDR output,
    int32_t B, int32_t H, int32_t xSeqLen, int32_t refSeqLen, int32_t numClasses,
    int32_t usedCoreNum, int32_t tasksPerCore, int64_t modeFlag,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(attn, masks, output, B, H, xSeqLen, refSeqLen, numClasses,
                    usedCoreNum, tasksPerCore, modeFlag, extraArgs...);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(attn, masks, output, B, H, xSeqLen, refSeqLen, numClasses,
                    usedCoreNum, tasksPerCore, modeFlag, extraArgs...);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(attn, masks, output, B, H, xSeqLen, refSeqLen, numClasses,
                    usedCoreNum, tasksPerCore, modeFlag, extraArgs...);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// modeFlag: 0=mean, 1=max
// =========================================================================

extern "C" __global__ __aicore__ void multi_mask_attention_agg_whole_r(
    GM_ADDR attn, GM_ADDR masks, GM_ADDR output,
    int32_t B, int32_t H, int32_t xSeqLen, int32_t refSeqLen, int32_t numClasses,
    int32_t usedCoreNum, int32_t tasksPerCore, int64_t modeFlag, int64_t dtypeFlag)
{
    DispatchKernel<WholeRKernel>(
        attn, masks, output, B, H, xSeqLen, refSeqLen, numClasses,
        usedCoreNum, tasksPerCore, modeFlag, dtypeFlag);
}

extern "C" __global__ __aicore__ void multi_mask_attention_agg_split_r(
    GM_ADDR attn, GM_ADDR masks, GM_ADDR output,
    int32_t B, int32_t H, int32_t xSeqLen, int32_t refSeqLen, int32_t numClasses,
    int32_t usedCoreNum, int32_t tasksPerCore, int64_t modeFlag, int64_t dtypeFlag)
{
    DispatchKernel<SplitRKernel>(
        attn, masks, output, B, H, xSeqLen, refSeqLen, numClasses,
        usedCoreNum, tasksPerCore, modeFlag, dtypeFlag);
}
