// MultiMaskAttentionAggregation op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD

#include <algorithm>
#include <cstdint>
#include <string>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_multi_mask_attention_agg_whole_r.h"
#include "aclrtlaunch_multi_mask_attention_agg_split_r.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_X = 4;
constexpr int32_t DEFAULT_BLOCK_R = 512;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor multi_mask_attention_aggregation(
    const at::Tensor &attn,
    const at::Tensor &ref_target_masks,
    std::string mode)
{
    // Input validation
    TORCH_CHECK(attn.dim() == 4, "attn must be 4D [B, H, x_seq_len, ref_seq_len]");
    TORCH_CHECK(ref_target_masks.dim() == 2, "ref_target_masks must be 2D [num_classes, ref_seq_len]");
    TORCH_CHECK(
        attn.scalar_type() == at::kFloat || attn.scalar_type() == at::kHalf ||
            attn.scalar_type() == at::kBFloat16,
        "attn must be float32, float16, or bfloat16");
    TORCH_CHECK(
        ref_target_masks.scalar_type() == attn.scalar_type(),
        "ref_target_masks must have the same dtype as attn");
    TORCH_CHECK(attn.is_contiguous(), "attn must be contiguous");
    TORCH_CHECK(ref_target_masks.is_contiguous(), "ref_target_masks must be contiguous");
    TORCH_CHECK(
        static_cast<int32_t>(attn.sizes()[3]) == static_cast<int32_t>(ref_target_masks.sizes()[1]),
        "ref_seq_len mismatch between attn and ref_target_masks");
    TORCH_CHECK(mode == "mean" || mode == "max", "mode must be 'mean' or 'max'");

    int32_t B = static_cast<int32_t>(attn.sizes()[0]);
    int32_t H = static_cast<int32_t>(attn.sizes()[1]);
    int32_t xSeqLen = static_cast<int32_t>(attn.sizes()[2]);
    int32_t refSeqLen = static_cast<int32_t>(attn.sizes()[3]);
    int32_t numClasses = static_cast<int32_t>(ref_target_masks.sizes()[0]);

    // Tiling computation
    int32_t xNumTiles = (xSeqLen + DEFAULT_BLOCK_X - 1) / DEFAULT_BLOCK_X;
    int32_t totalTasks = numClasses * B * xNumTiles;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, totalTasks));
    int32_t tasksPerCore = (totalTasks + usedCoreNum - 1) / usedCoreNum;

    // Allocate output tensor
    at::Tensor output = at::empty({numClasses, B, xSeqLen}, attn.options());

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (attn.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (attn.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // mode flag: 0=mean, 1=max
    int64_t modeFlag = (mode == "max") ? 1 : 0;

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int32_t blockX = DEFAULT_BLOCK_X;

    // Strategy dispatch: select kernel based on ref_seq_len
    if (refSeqLen <= 1024) {
        EXEC_KERNEL_CMD(multi_mask_attention_agg_whole_r, blockDim,
                        attn, ref_target_masks, output,
                        B, H, xSeqLen, refSeqLen, numClasses,
                        usedCoreNum, tasksPerCore, modeFlag, dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(multi_mask_attention_agg_split_r, blockDim,
                        attn, ref_target_masks, output,
                        B, H, xSeqLen, refSeqLen, numClasses,
                        usedCoreNum, tasksPerCore, modeFlag, dtypeFlag);
    }

    return output;
}

}  // namespace ascend_kernel
