    int32_t usedCoreNum, int32_t tasksPerCore, int64_t modeFlag, int64_t dtypeFlag)
{
    DispatchKernel<SplitRKernel>(attn, masks, output, B, H, xSeqLen, refSeqLen,
        numClasses, usedCoreNum, tasksPerCore, modeFlag, dtypeFlag);
}
